-- 重新开始按钮 - 重新开始当前关卡
function XUiLuckyTenant2PopupNormal:OnBtnRestartClick(eventData)
    -- 获取当前游戏对象
    local game = self._Control._Game
    if not game then
        XUiManager.TipText("LuckyTenant2NoPlayingStage")
        self:Close()
        return
    end
    
    local stageId = game:GetStageId()
    if not stageId or stageId <= 0 then
        XUiManager.TipText("LuckyTenant2NoPlayingStage")
        self:Close()
        return
    end

    -- 调用重开接口（会发送重开协议并收集结算数据）
    XMVCA.XLuckyTenant2:RequestRestart(game, function()
        -- 关闭当前弹窗和游戏界面
        self:Close()
        XLuaUiManager.Remove("UiLuckyTenant2Game")

        -- 请求服务器开始新游戏
        XMVCA.XLuckyTenant2:RequestStart(stageId, function(playingStage)
            -- 服务器返回成功后打开游戏界面
            -- playingStage 包含恢复游戏所需的 record 数据
            local seed = XTime.GetServerNowTimestamp()
            local isFirstTimeEntering = true
            XLuaUiManager.Open("UiLuckyTenant2Game", stageId, seed, isFirstTimeEntering, playingStage)
        end)
    end)
end

