function XUiLuckyTenant2PopupNormal:OnBtnOverClick(eventData)
    -- 调用 Control 的方法结束游戏（会自动处理离线模式和收集结算数据）
    self._Control:RequestEndGame(function(success)
        -- 无论成功失败，都关闭弹窗和游戏界面
        XLuaUiManager.Remove("UiLuckyTenant2Game")
        self:Close()
    end)
end

